//! The MHPCO price list: what each insurable item costs to cover, before any
//! risk assessment or customer standing is taken into account.
//!
//! This is the catalog side of the office's knowledge. It changes when the
//! MHPCO revises its prices or its building-block offer, independently of the
//! underwriting rules that surcharge and discount a policy.

use std::collections::BTreeMap;

use crate::Item;

const SWORD_BASE_PREMIUM: f64 = 100.0;
const AMULET_BASE_PREMIUM: f64 = 60.0;
const STAFF_BASE_PREMIUM: f64 = 80.0;
const POTION_BASE_PREMIUM: f64 = 40.0;
const COMPONENT_BASE_PREMIUM: f64 = 25.0;
const COMPONENT_BLOCK_SIZE: usize = 3;
const COMPONENT_BLOCK_BASE_PREMIUM: f64 = 60.0;

/// Components are the small insurable parts the MHPCO lists apart from main
/// items: they are priced per component and may form building blocks.
fn is_component(item: &Item) -> bool {
    matches!(item.item_type.as_str(), "rune" | "moonstone")
}

/// The MHPCO price list: the base premium each insurable main item carries.
/// Components are not priced here; they are priced per building block.
///
/// An item type the price list does not name is not yet refused -- the office
/// has no rule for it on the books -- so it falls through to the sword price.
fn main_item_base_premium(item: &Item) -> f64 {
    match item.item_type.as_str() {
        "amulet" => AMULET_BASE_PREMIUM,
        "staff" => STAFF_BASE_PREMIUM,
        "potion" => POTION_BASE_PREMIUM,
        _ => SWORD_BASE_PREMIUM,
    }
}

/// A building block of alike components is offered at a special base premium.
fn component_group_base_premium(count: usize) -> f64 {
    if count == COMPONENT_BLOCK_SIZE {
        COMPONENT_BLOCK_BASE_PREMIUM
    } else {
        count as f64 * COMPONENT_BASE_PREMIUM
    }
}

/// Components are alike when they are of the very same type: the MHPCO reads
/// "3 alike components" strictly, so runes and moonstones never share a block.
fn alike_component_kind(item: &Item) -> &str {
    item.item_type.as_str()
}

/// The base premium of all components in a policy: components of the same kind
/// are counted together so that their building block can apply.
fn components_base_premium(items: &[Item]) -> f64 {
    let mut counts: BTreeMap<&str, usize> = BTreeMap::new();
    for item in items.iter().filter(|item| is_component(item)) {
        *counts.entry(alike_component_kind(item)).or_default() += 1;
    }
    counts.into_values().map(component_group_base_premium).sum()
}

/// The base premium of all main items in a policy, straight from the price list.
fn main_items_base_premium(items: &[Item]) -> f64 {
    items
        .iter()
        .filter(|item| !is_component(item))
        .map(main_item_base_premium)
        .sum()
}

/// The policy base premium: the sum of the base premiums of all insured items.
pub(crate) fn policy_base_premium(items: &[Item]) -> f64 {
    main_items_base_premium(items) + components_base_premium(items)
}

/// The base premium an item-specific modifier is measured against: the item's
/// own listed price, which for a component is the per-component premium.
pub(crate) fn item_base_premium(item: &Item) -> f64 {
    if is_component(item) {
        COMPONENT_BASE_PREMIUM
    } else {
        main_item_base_premium(item)
    }
}
//! What the MHPCO reimburses for a single reported damage: the clauses the
//! office applies to one damage amount before it reaches the settlement.
//!
//! This is the claim side's judgement of a single damage event. It changes
//! when the office revises its clauses -- a steeper deductible, a new
//! material that is fully covered, a different enchantment level -- quite
//! independently of the policy-wide limits on what a settlement may total,
//! and independently of how the premium side assessed the same item's risk.

use crate::{Damage, Item};

/// A deductible applies per damage event.
const DEDUCTIBLE: i64 = 100;

/// Damage to an item enchanted at this level or above is reimbursed at half.
const HALF_REIMBURSEMENT_LEVEL: i64 = 8;

/// Whether the half-reimbursement clause applies to an insured item. The claim
/// side judges high enchantment by its own level, well above the one the
/// premium side surcharges for.
fn half_reimbursement_applies(item: &Item) -> bool {
    item.enchantment >= HALF_REIMBURSEMENT_LEVEL
}

/// Which share of a reported damage the office's clauses cover, before the
/// deductible. The MHPCO reimburses in full unless a clause of its own cuts
/// the share down, and a damage to no recognised item meets no clause at all.
fn covered_amount(damage: &Damage, damaged: Option<&Item>) -> i64 {
    if damaged.is_some_and(half_reimbursement_applies) {
        damage.amount / 2
    } else {
        damage.amount
    }
}

/// What the MHPCO reimburses for one reported damage: the share of the
/// damage the office covers, less the deductible the claimant bears
/// themselves.
pub(crate) fn damage_reimbursement(damage: &Damage, damaged: Option<&Item>) -> i64 {
    covered_amount(damage, damaged) - DEDUCTIBLE
}
//! The MHPCO's risk assessment of a single insured item: which properties of
//! an item the office judges hazardous, and what surcharge each one carries.
//!
//! This is the underwriting side's view of an item's danger. It changes when
//! the office revises its risk appetite -- a steeper curse surcharge, a new
//! hazardous property -- independently of the customer's standing, of the
//! price list, and of how a claim later judges the same item.

use crate::pricing::item_base_premium;
use crate::Item;

const CURSE_SURCHARGE: f64 = 0.50;
const HIGH_ENCHANTMENT_SURCHARGE: f64 = 0.30;
const HIGH_ENCHANTMENT_LEVEL: i64 = 5;

/// An item counts as highly enchanted for the premium's risk assessment from
/// the MHPCO's listed enchantment level upwards. The claim side judges high
/// enchantment by its own, separate level.
fn is_highly_enchanted(item: &Item) -> bool {
    item.enchantment >= HIGH_ENCHANTMENT_LEVEL
}

/// The risk surcharge rate a single item carries, as a share of its own base
/// premium: the MHPCO's item-specific risk assessment.
fn item_surcharge_rate(item: &Item) -> f64 {
    let mut rate = 0.0;
    if item.cursed {
        rate += CURSE_SURCHARGE;
    }
    if is_highly_enchanted(item) {
        rate += HIGH_ENCHANTMENT_SURCHARGE;
    }
    rate
}

/// What the policy's hazardous items add to its premium: each affected item
/// surcharges its own base premium, never the rest of the policy.
pub(crate) fn item_risk_surcharges(items: &[Item]) -> f64 {
    items
        .iter()
        .map(|item| item_base_premium(item) * item_surcharge_rate(item))
        .sum()
}
//! How a customer's standing with the MHPCO bears on the premium: the
//! policy-wide modifiers the office grants or levies for loyalty, for a first
//! insurance, and for a contract that follows an earlier one.
//!
//! This is the customer-relations side of the office's knowledge. It changes
//! when the MHPCO courts or squeezes its customers -- a longer loyalty
//! qualification, a deeper follow-up discount -- independently of how
//! hazardous any insured item happens to be.

use crate::Customer;

const FIRST_INSURANCE_SURCHARGE: f64 = 0.10;
const LOYALTY_DISCOUNT: f64 = 0.20;
const LOYALTY_YEARS: i64 = 2;
const FOLLOW_UP_CONTRACT_DISCOUNT: f64 = 0.15;

/// A long-standing customer has been with the MHPCO for at least two years.
fn is_long_standing(customer: &Customer) -> bool {
    customer.years_with_mhpco >= LOYALTY_YEARS
}

/// Long-standing customers are rewarded with a discount on the policy.
fn loyalty_rate(customer: &Customer) -> f64 {
    if is_long_standing(customer) {
        -LOYALTY_DISCOUNT
    } else {
        0.0
    }
}

/// Every contract after the customer's first is discounted.
fn follow_up_contract_rate(previous_quotes: usize) -> f64 {
    if previous_quotes > 0 {
        -FOLLOW_UP_CONTRACT_DISCOUNT
    } else {
        0.0
    }
}

/// Every quote insures its items for the first time, so the initial assessment
/// surcharge is carried unconditionally: the MHPCO reads "first insurance" as
/// the item's, not the customer's, so customer history never waives it.
fn first_insurance_rate() -> f64 {
    FIRST_INSURANCE_SURCHARGE
}

/// The net policy-wide modifier rate the customer's circumstances carry, as a
/// share of the policy base premium. The MHPCO sums its policy-wide modifiers
/// rather than compounding them, so each one contributes its own rate here.
fn policy_modifier_rate(customer: &Customer, previous_quotes: usize) -> f64 {
    first_insurance_rate() + loyalty_rate(customer) + follow_up_contract_rate(previous_quotes)
}

/// What the customer's standing adds to or takes off the policy base premium.
pub(crate) fn standing_adjustment(
    base: f64,
    customer: &Customer,
    previous_quotes: usize,
) -> f64 {
    base * policy_modifier_rate(customer, previous_quotes)
}

