//! What a policy costs the customer: how the MHPCO composes one premium out of
//! the price list, its risk assessment, and the customer's standing.
//!
//! This is the office's underwriting arithmetic -- the order in which the two
//! kinds of modifier reach the premium, the rounding the office allows itself,
//! and the fee it levies on every contract. It changes when the MHPCO revises
//! how its modifiers stack, independently of what any single modifier is worth.

use crate::pricing::policy_base_premium;
use crate::risk::item_risk_surcharges;
use crate::standing::standing_adjustment;
use crate::{Customer, Item};

/// A processing fee is levied on every premium, after all other arithmetic.
const PROCESSING_FEE: i64 = 5;

/// A premium is rounded in the MHPCO's favor, which for money the customer
/// owes the office means upwards.
fn round_premium_in_mhpco_favor(premium: f64) -> i64 {
    premium.ceil() as i64
}

/// How the MHPCO's two kinds of modifier reach the premium: policy-wide
/// modifiers scale the policy base premium, while item-specific modifiers are
/// measured against their own item's base premium and are added alongside, so
/// a curse never surcharges the rest of the policy.
fn premium_before_fee(customer: &Customer, items: &[Item], previous_quotes: usize) -> f64 {
    let base = policy_base_premium(items);
    base + standing_adjustment(base, customer, previous_quotes) + item_risk_surcharges(items)
}

/// What the MHPCO charges to insure a policy's items for this customer.
pub(crate) fn policy_premium(customer: &Customer, items: &[Item], previous_quotes: usize) -> i64 {
    let premium = premium_before_fee(customer, items, previous_quotes);
    round_premium_in_mhpco_favor(premium) + PROCESSING_FEE
}
